//go:generate echo "Comment extraction would happen here - struct-tag-parser integration"

package main

import (
	"fmt"
	"os"
	"regexp"
	"strings"

	"github.com/davidwalter0/go-cfg/pkg/flags"
)

// AppConfig represents the complete application configuration
// These tags would normally be generated by go:generate struct-tag-parser from comments
type AppConfig struct {
	// Basic application settings (comments would be extracted to usage tags)
	ServiceName string `usage:"Application service name" default:"my-service"`
	Environment string `usage:"Deployment environment (dev|staging|prod)" default:"development"`
	Version     string `usage:"Application version" default:"1.0.0"`
	Debug       bool   `usage:"Enable debug mode for development"`

	// External service URLs
	APIEndpoint string `usage:"External API endpoint URL" default:"https://api.example.com"`
	WebhookURL  string `usage:"Webhook callback URL"`

	// Performance settings
	WorkerCount    int      `usage:"Number of worker goroutines" default:"10"`
	RequestTimeout string   `usage:"Default request timeout" default:"30s"`
	AllowedOrigins []string `usage:"CORS allowed origins" default:"localhost,127.0.0.1"`

	// Nested configuration structures
	Database   DatabaseConfig   `usage:"Database connection settings"`
	Server     ServerConfig     `usage:"HTTP server configuration"`
	Monitoring MonitoringConfig `usage:"Monitoring and observability settings"`
}

// showDetailedUsage displays help text with environment variable mappings
func showDetailedUsage(fc *flags.FlagConfig) {
	// Get the basic usage first
	basicUsage := fc.Usage()

	// Split into lines and enhance each line with env var info
	lines := strings.Split(basicUsage, "\n")

	for _, line := range lines {
		if strings.TrimSpace(line) == "" {
			fmt.Println()
			continue
		}

		// Parse flag line format: "      --flag-name type    description (default value)"
		if strings.Contains(line, "--") {
			// Extract flag name (handle multi-part names with dashes)
			flagRegex := regexp.MustCompile(`--([a-z-]+(?:-[a-z-]+)*)`)
			matches := flagRegex.FindStringSubmatch(line)
			if len(matches) > 1 {
				flagName := matches[1]
				envVar := flagToEnvVar(flagName)

				// Insert [env: ENV_VAR] before (default ...)
				enhanced := line
				if strings.Contains(line, "(default") {
					parts := strings.Split(line, "(default")
					if len(parts) == 2 {
						enhanced = parts[0] + fmt.Sprintf("[env: %s] (default%s", envVar, parts[1])
					}
				} else {
					// No default, just append env info
					enhanced = line + fmt.Sprintf(" [env: %s]", envVar)
				}
				fmt.Println(enhanced)
			} else {
				fmt.Println(line)
			}
		} else {
			fmt.Println(line)
		}
	}
}

// flagToEnvVar converts kebab-case flag names to SCREAMING_SNAKE_CASE env vars
func flagToEnvVar(flagName string) string {
	// Convert kebab-case to SCREAMING_SNAKE_CASE
	envVar := strings.ReplaceAll(flagName, "-", "_")
	return strings.ToUpper(envVar)
}

func main() {
	// Initialize configuration with some defaults
	config := &AppConfig{
		ServiceName:    "my-service",
		Environment:    "development",
		Version:        "1.0.0",
		APIEndpoint:    "https://api.example.com",
		WorkerCount:    10,
		RequestTimeout: "30s",
		AllowedOrigins: []string{"localhost", "127.0.0.1"},
	}

	// Check for help flag first before parsing (to handle it ourselves)
	for _, arg := range os.Args[1:] {
		if arg == "-h" || arg == "--help" {
			// Create flag configuration
			fc := flags.NewFlagConfig()

			// Register all configuration fields (including nested structs)
			if err := fc.RegisterCustomTypes(config); err != nil {
				fmt.Fprintf(os.Stderr, "Failed to register configuration: %v\n", err)
				os.Exit(1)
			}

			fmt.Printf("Usage of %s:\n", os.Args[0])
			showDetailedUsage(fc)

			fmt.Printf("\nExample usage:\n")
			fmt.Printf("  %s --service-name \"my-api\" --debug --worker-count 20\n", os.Args[0])
			fmt.Printf("  %s --database-host \"prod-db.com\" --server-port 8080\n", os.Args[0])
			fmt.Printf("  %s --monitoring-log-level \"warn\" --monitoring-enable-metrics\n", os.Args[0])

			fmt.Printf("\nEnvironment variable examples:\n")
			fmt.Printf("  export SERVICE_NAME=\"my-api\"\n")
			fmt.Printf("  export DATABASE_HOST=\"prod-db.company.com\"\n")
			fmt.Printf("  export MONITORING_LOG_LEVEL=\"warn\"\n")
			fmt.Printf("  export SERVER_PORT=9000\n")
			return
		}
	}

	// Create flag configuration
	fc := flags.NewFlagConfig()

	// Register all configuration fields (including nested structs)
	if err := fc.RegisterCustomTypes(config); err != nil {
		fmt.Fprintf(os.Stderr, "Failed to register configuration: %v\n", err)
		os.Exit(1)
	}

	// Parse command line arguments
	if err := fc.Parse(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "Failed to parse flags: %v\n", err)

		// Show detailed usage on parse error
		fmt.Fprintf(os.Stderr, "\nUsage:\n")
		showDetailedUsage(fc)
		os.Exit(1)
	}

	// Display final configuration
	fmt.Printf("=== Configuration Loaded ===\n")
	fmt.Printf("Service: %s (v%s) [%s]\n", config.ServiceName, config.Version, config.Environment)
	fmt.Printf("Debug Mode: %t\n", config.Debug)
	fmt.Printf("API Endpoint: %s\n", config.APIEndpoint)
	fmt.Printf("Workers: %d, Timeout: %s\n", config.WorkerCount, config.RequestTimeout)
	fmt.Printf("Allowed Origins: %v\n", config.AllowedOrigins)

	fmt.Printf("\nDatabase: %s@%s:%d/%s (SSL: %s, MaxConns: %d)\n",
		config.Database.Username, config.Database.Host, config.Database.Port,
		config.Database.Database, config.Database.SSLMode, config.Database.MaxConns)

	fmt.Printf("Server: %s:%d (TLS: %t)\n",
		config.Server.Host, config.Server.Port, config.Server.EnableTLS)

	fmt.Printf("Monitoring: Metrics=%t:%d, Tracing=%t, LogLevel=%s\n",
		config.Monitoring.EnableMetrics, config.Monitoring.MetricsPort,
		config.Monitoring.EnableTracing, config.Monitoring.LogLevel)

	fmt.Printf("\nRun with --help to see all available options\n")
}
